\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Seasonal Price Spreads in Regional Onion Markets}
\author{R. Okafor}
\date{}

\begin{document}
\maketitle

\section{Introduction}
\label{intro}
Seasonal price spreads in staple vegetable markets remain
poorly documented for the region.
This note assembles three harvest cycles of wholesale prices
and asks how much of the spread storage can explain.

\section{Model}
\label{model}
The storage arbitrage condition equates the price difference
between harvest and lean seasons with the cost of storage,
credit, and expected spoilage.
Section~\ref{results} confronts this benchmark with the data.

\section{Results}
\label{results}
Measured spreads exceed the storage-cost benchmark in seven
of nine market years.
As anticipated in Section~\ref{model}, the excess is largest
where rural credit is thinnest.

\end{document}

